INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.104.0',
  '2026-09-29',
  'Пульт ТВ: постеры находятся там, где раньше не находились',
  E'У части фильмов постер не появлялся — «Элизиум», «Почти 17», две «Фантастические твари». Теперь агент ищет тремя названиями подряд: как называется файл, как называется его начало до двоеточия или тире, и как фильм назван внутри самого файла. Последнее выручает русские раздачи: имя файла бывает транслитом («PoCHti.17.2016»), а в метаданных лежит нормальное английское название.\n\nИ сравнение названий стало терпимее: двоеточие против тире, «ё» против «е», разный регистр больше не мешают. Именно из-за этого не находились «Фантастические твари: Преступления Грин-де-Вальда» — в Википедии двоеточие, а в имени файла тире.\n\nВсе 11 фильмов и 7 сериалов на приставке теперь с постерами.',
  E'media-agent, catalog.go: normTitle() — сравнение названий по буквам и цифрам, без знаков препинания и регистра, ё→е. Применено в wikiPoster, wikiSearchTitle (info.go) и imdbFind: раньше там было strings.ToLower + равенство/префикс, и «Элизиум — рай не на Земле» (Википедия, длинное тире) не совпадало с «Элизиум - Рай не на Земле» (наше имя файла).\n\ntitleTries(path, isDir, title, year) — до четырёх попыток: имя файла; его начало до «:» или « — » (reTitleTail), если осталось ≥3 знаков; название из тега title контейнера (ffprobe -show_entries format_tags=title), разобранное cleanTitle и разбитое по «/» («Мама / Mama (2013)» — два названия). Попытки из метаданных помечены strict: найденное принимается только при совпадении года ±1, иначе подпись рипера вроде «-=LEONARDO=-» притащила бы чужой постер. Кракозябры (U+FFFD) и строки меньше трёх букв отбрасываются сразу.\n\nfindPosterFor и lookupInfo идут по этим попыткам до первого успеха; дальше всё как было (IMDb → Википедия для латиницы, Википедия → IMDb для кириллицы).\n\nПроверено вживую: постеры нашлись у всех четырёх «потерянных» фильмов, «Почти 17» — именно через тег внутри файла (синтетический mkv с таким же тегом в тесте). На приставке сняты отметки о неудачном поиске (.miss), после обновления агент нашёл постеры всем 18 плиткам; глазами сверены «Почти 17», «Элизиум» и «Тайны Дамблдора» — постеры правильные.'
);
-- +goose StatementEnd

